CREATE TABLE automation_rules (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  trigger_key TEXT NOT NULL,   -- e.g. task.sla_breached
  action_key  TEXT NOT NULL,   -- e.g. escalate.assign
  config_json TEXT NOT NULL DEFAULT '{}',
  is_enabled  INTEGER NOT NULL DEFAULT 1,
  run_count   INTEGER NOT NULL DEFAULT 0,
  last_run_at TEXT,
  created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS'))
);

CREATE TABLE notifications (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind        TEXT NOT NULL,
  title       TEXT NOT NULL,
  body        TEXT NOT NULL DEFAULT '',
  entity_type TEXT NOT NULL DEFAULT '',
  entity_id   TEXT NOT NULL DEFAULT '',
  read_at     TEXT,
  created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS'))
);
CREATE INDEX idx_notif_user ON notifications(user_id, read_at);

CREATE TABLE saved_views (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  owner_id   TEXT REFERENCES users(id) ON DELETE CASCADE,
  surface    TEXT NOT NULL DEFAULT 'board',
  filters_json TEXT NOT NULL DEFAULT '{}',
  is_shared  INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS'))
);

-- Capacity snapshots feed the planner + forecasting charts.
CREATE TABLE capacity_snapshots (
  id             TEXT PRIMARY KEY,
  user_id        TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  week_start     TEXT NOT NULL,
  capacity_hours DOUBLE PRECISION NOT NULL,
  planned_hours  DOUBLE PRECISION NOT NULL DEFAULT 0,
  logged_hours   DOUBLE PRECISION NOT NULL DEFAULT 0,
  UNIQUE (user_id, week_start)
);

-- Output of the deterministic scheduler; each run is persisted so plans are
-- explainable and auditable ("why did the engine move this task?").
CREATE TABLE schedule_runs (
  id           TEXT PRIMARY KEY,
  created_by   TEXT REFERENCES users(id),
  algorithm    TEXT NOT NULL DEFAULT 'cpm+wspt',
  horizon_days INTEGER NOT NULL DEFAULT 21,
  input_hash   TEXT NOT NULL DEFAULT '',
  stats_json   TEXT NOT NULL DEFAULT '{}',
  created_at   TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS'))
);

CREATE TABLE schedule_items (
  id             TEXT PRIMARY KEY,
  run_id         TEXT NOT NULL REFERENCES schedule_runs(id) ON DELETE CASCADE,
  task_id        TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  assignee_id    TEXT REFERENCES users(id),
  sequence       INTEGER NOT NULL,
  planned_start  TEXT NOT NULL,
  planned_end    TEXT NOT NULL,
  planned_hours  DOUBLE PRECISION NOT NULL,
  risk_score     DOUBLE PRECISION NOT NULL DEFAULT 0,
  rationale      TEXT NOT NULL DEFAULT ''
);
CREATE INDEX idx_schedule_items_run ON schedule_items(run_id, sequence);

CREATE TABLE risk_scores (
  id          TEXT PRIMARY KEY,
  entity_type TEXT NOT NULL CHECK (entity_type IN ('task','project','deal')),
  entity_id   TEXT NOT NULL,
  score       DOUBLE PRECISION NOT NULL,
  band        TEXT NOT NULL CHECK (band IN ('low','medium','high','critical')),
  factors_json TEXT NOT NULL DEFAULT '[]',
  computed_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS'))
);
CREATE INDEX idx_risk_entity ON risk_scores(entity_type, entity_id, computed_at DESC);

CREATE TABLE audit_log (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  actor_id    TEXT,
  action      TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id   TEXT NOT NULL,
  before_json TEXT NOT NULL DEFAULT 'null',
  after_json  TEXT NOT NULL DEFAULT 'null',
  request_id  TEXT NOT NULL DEFAULT '',
  ip          TEXT NOT NULL DEFAULT '',
  created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS'))
);
CREATE INDEX idx_audit_entity ON audit_log(entity_type, entity_id);
CREATE INDEX idx_audit_created ON audit_log(created_at DESC);

-- Excalidraw "excaliboard" handoff links discussed in the pipeline review.
CREATE TABLE handoffs (
  id            TEXT PRIMARY KEY,
  project_id    TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  project_phase_id TEXT REFERENCES project_phases(id) ON DELETE SET NULL,
  title         TEXT NOT NULL,
  type          TEXT NOT NULL DEFAULT 'excalidraw'
                CHECK (type IN ('excalidraw','figma','loom','notion','drive','other')),
  url           TEXT NOT NULL,
  shared_with   TEXT NOT NULL DEFAULT 'client',
  status        TEXT NOT NULL DEFAULT 'draft'
                CHECK (status IN ('draft','ready','shared','approved','changes_requested')),
  created_by    TEXT REFERENCES users(id),
  shared_at     TEXT,
  created_at    TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS'))
);
CREATE INDEX idx_handoffs_project ON handoffs(project_id);

CREATE TABLE retention_policies (
  id          TEXT PRIMARY KEY,
  table_name  TEXT NOT NULL UNIQUE,
  retain_days INTEGER NOT NULL,
  description TEXT NOT NULL DEFAULT '',
